/** Beatpd's 16 pads, generated by scripts/make-kit.py. */
export type Group = 'Drums' | 'Perc' | 'Bass' | 'Keys';

export interface Pad {
  id: string;
  label: string;
  group: Group;
  source: number;
}

export const GROUP_COLORS: Record<Group, string> = {
  Drums: '#F43F5E',
  Perc: '#F59E0B',
  Bass: '#22D3EE',
  Keys: '#A78BFA',
};

export const pads: Pad[] = [
  { id: 'kick', label: 'Kick', group: 'Drums', source: require('@/assets/sounds/kick.wav') },
  { id: 'snare', label: 'Snare', group: 'Drums', source: require('@/assets/sounds/snare.wav') },
  { id: 'clap', label: 'Clap', group: 'Drums', source: require('@/assets/sounds/clap.wav') },
  { id: 'hat', label: 'Hat', group: 'Drums', source: require('@/assets/sounds/hat.wav') },
  { id: 'open-hat', label: 'Open hat', group: 'Perc', source: require('@/assets/sounds/open-hat.wav') },
  { id: 'tom', label: 'Tom', group: 'Perc', source: require('@/assets/sounds/tom.wav') },
  { id: 'rim', label: 'Rim', group: 'Perc', source: require('@/assets/sounds/rim.wav') },
  { id: 'shaker', label: 'Shaker', group: 'Perc', source: require('@/assets/sounds/shaker.wav') },
  { id: 'bass-a', label: 'A', group: 'Bass', source: require('@/assets/sounds/bass-a.wav') },
  { id: 'bass-c', label: 'C', group: 'Bass', source: require('@/assets/sounds/bass-c.wav') },
  { id: 'bass-d', label: 'D', group: 'Bass', source: require('@/assets/sounds/bass-d.wav') },
  { id: 'bass-e', label: 'E', group: 'Bass', source: require('@/assets/sounds/bass-e.wav') },
  { id: 'keys-am', label: 'Am', group: 'Keys', source: require('@/assets/sounds/keys-am.wav') },
  { id: 'keys-c', label: 'C', group: 'Keys', source: require('@/assets/sounds/keys-c.wav') },
  { id: 'keys-dm', label: 'Dm', group: 'Keys', source: require('@/assets/sounds/keys-dm.wav') },
  { id: 'keys-em', label: 'Em', group: 'Keys', source: require('@/assets/sounds/keys-em.wav') },
];

/** The sequencer's four tracks. */
export const TRACKS = ['kick', 'snare', 'hat', 'bass-a'] as const;
export const STEPS = 16;

/** A starter groove so the loop sounds good on first play. */
export const starterPattern: Record<(typeof TRACKS)[number], boolean[]> = {
  kick: Array.from({ length: STEPS }, (_, i) => [0, 6, 10].includes(i)),
  snare: Array.from({ length: STEPS }, (_, i) => i === 4 || i === 12),
  hat: Array.from({ length: STEPS }, (_, i) => i % 2 === 0),
  'bass-a': Array.from({ length: STEPS }, (_, i) => [0, 3, 8, 11].includes(i)),
};
